export function solve(times, limit, windowMs) {
  let lastWindow;
  let count = 0;

  return times.map(t => {
    const window = Math.floor(t / windowMs);
    if (window !== lastWindow) {
      count = 0;
      lastWindow = window;
    }

    if (count < limit) {
      count++;
      return true;
    }
    return false;
  });
}
```

The restored invariant is that `count` tracks accepted events in the current fixed window. It resets only when the window changes, not whenever the timestamp changes. Thus `solve([0, 1], 1, 2)` returns `[true, false]`, enforcing the shared window’s quota.

